  $$(".fpr",v).forEach(x=>x.onchange=async ()=>{ x.disabled=true; const p=perfilAtual(); try{ await setLinha(k,x.dataset.id, x.checked?{pronto:true, prontoPor:p?p.nome:"", prontoEm:nowIso()}:{pronto:false, prontoPor:"", prontoEm:""}); }catch(e){ toast(dbErr(e),"bad"); x.checked=!x.checked; x.disabled=false; } });
